  app2.post(
    "/api/medications",
    requirePermission("clinical.create"),
    async (req, res) => {
      try {
        if (!req.authContext) {
          return res.status(401).json({
            success: false,
            error: "AUTHORIZATION_CONTEXT_MISSING"
          });
        }
        const body = req.body ?? {};
        const patientId = Number(body.patientId);
        const drugName = typeof body.drugName === "string" ? body.drugName.trim() : "";
        if (Number.isSafeInteger(patientId) && patientId > 0 && drugName !== "") {
          const check = await checkMedicationAllergies(
            req.authContext,
            patientId,
            [drugName]
          );
          if (check.warnings.length > 0) {
            const acknowledged = body.allergyAcknowledged === true;
            if (!acknowledged) {
              return res.status(409).json({
                success: false,
                error: "ALLERGY_CONFLICT",
                message: "This patient has a recorded allergy that matches this medication. Confirm to prescribe anyway.",
                warnings: check.warnings,
                disclaimer: check.disclaimer,
                detail: {
                  warnings: check.warnings,
                  disclaimer: check.disclaimer
                }
              });
            }
            await logAuditEvent(
              req.authContext.tenantId,
              req.authContext.facilityId,
              String(req.authContext.userId),
              "PRESCRIBE",
              "Medication",
              null,
              `Allergy warning overridden for ${drugName}: ${check.warnings.map((warning) => warning.allergen).join(", ")}`
            );
          }
        }
        const { allergyAcknowledged: _acknowledged, ...payload } = body;
        const med = await createMedication(
          payload
        );
        res.status(201).json(med);
      } catch (err) {
        if (handleScopeError(err, res)) return;
        res.status(500).json({
          error: err.message
        });
      }
    }
  );
