// server.ts
var PORT2 = Number(process.env.PORT ?? 3e3);
var app;
var httpServer;
var shuttingDown = false;
async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`Received ${signal}; shutting down JaliCare HMIS...`);
  const timeout = setTimeout(() => {
    console.error("Graceful shutdown timed out.");
    process.exit(1);
  }, 1e4);
  timeout.unref();
  try {
    if (httpServer) {
      await new Promise((resolve, reject) => {
        httpServer.close((error) => {
          if (error) {
            reject(error);
          } else {
            resolve();
          }
        });
      });
    }
    const closeResources = app?.locals.closeResources;
    if (typeof closeResources === "function") {
      await closeResources();
    }
    await pool.end();
    console.log("JaliCare HMIS shutdown completed.");
  } catch (error) {
    console.error("Error during server shutdown:", error);
    process.exitCode = 1;
  } finally {
    clearTimeout(timeout);
  }
}
process.on("SIGINT", () => {
  void shutdown("SIGINT");
});
process.on("SIGTERM", () => {
  void shutdown("SIGTERM");
});
async function startServer() {
  app = await createApp();
  httpServer = app.listen(PORT2, "0.0.0.0", () => {
    console.log(
      `JaliCare HMIS server running on http://0.0.0.0:${PORT2}`
    );
  });
}
startServer().catch(async (error) => {
  console.error("Fatal server startup error:", error);
  try {
    await pool.end();
  } catch (closeError) {
    console.error("Failed to close database pool:", closeError);
  }
  process.exitCode = 1;
});
